<?php
declare(strict_types=1);
function spend_strategy_period_default(): array{$end=date('Y-m-d');$start=date('Y-m-01',strtotime('-11 months',strtotime($end)));return[$start,$end];}
function spend_strategy_contract_for(array $contracts,int $supplierId,int $companyId,string $date):?array{foreach($contracts as $contract){if((int)($contract['supplier_id']??0)!==$supplierId)continue;$scope=$contract['company_id']??null;if($scope!==null&&(int)$scope!==$companyId)continue;if(!in_array((string)($contract['status']??''),['active','expiring'],true))continue;if(!empty($contract['start_date'])&&$date<(string)$contract['start_date'])continue;if(!empty($contract['end_date'])&&$date>(string)$contract['end_date'])continue;return$contract;}return null;}
function spend_strategy_invoice_by_po(string $start,string $end):array{if(data_is_demo())return[];$pdo=production_database_connection();if(!$pdo)return[];try{$check=$pdo->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='supplier_invoices'");if((int)$check->fetchColumn()!==1)return[];$stmt=$pdo->prepare('SELECT purchase_order_id,SUM(total_amount) invoiced_spend,SUM(CASE WHEN status IN ("released","paid","approved") THEN total_amount ELSE 0 END) payment_ready_spend FROM supplier_invoices WHERE invoice_date BETWEEN ? AND ? GROUP BY purchase_order_id');$stmt->execute([$start,$end]);$out=[];foreach($stmt->fetchAll()as$row)$out[(int)$row['purchase_order_id']]=$row;return$out;}catch(Throwable){return[];}}
function spend_strategy_validated_savings_by_category():array{$out=[];foreach(data_visible_collection('savings_opportunities')as$row){if(!in_array((string)($row['accounting_validation']??''),['validated','closed'],true))continue;$category=(int)($row['category_id']??0);$out[$category]=($out[$category]??0)+(float)($row['realized_savings']??0);}return$out;}
function spend_strategy_build_cube(string $start,string $end):array
{
$pos=array_values(array_filter(data_visible_collection('purchase_orders'),static fn(array $po):bool=>(string)($po['order_date']??'')>=$start&&(string)($po['order_date']??'')<=$end&&!in_array((string)($po['status']??''),['draft','canceled'],true)));$poById=[];foreach($pos as$po)$poById[(int)$po['id']]=$po;$lines=array_values(array_filter(data_collection('purchase_order_lines'),static fn(array $line):bool=>isset($poById[(int)($line['purchase_order_id']??0)])));$contracts=data_collection('contracts');$suppliers=[];foreach(data_collection('suppliers')as$s)$suppliers[(int)$s['id']]=$s;$items=[];foreach(data_collection('items')as$i)$items[(int)$i['id']]=$i;$invoiceByPo=spend_strategy_invoice_by_po($start,$end);$cube=[];
foreach($lines as$line){$po=$poById[(int)$line['purchase_order_id']];$company=(int)$po['company_id'];$supplier=(int)$po['supplier_id'];$item=$items[(int)($line['item_id']??0)]??[];$category=(int)($line['category_id']??($item['category_id']??0));$key=$company.':'.$category.':'.$supplier;$ordered=(float)($line['line_total']??((float)$line['quantity_ordered']*(float)$line['unit_cost']));$received=(float)($line['quantity_received']??0)*(float)($line['unit_cost']??0);$open=max(0,(float)$line['quantity_ordered']-(float)($line['quantity_received']??0))*(float)$line['unit_cost'];$contract=spend_strategy_contract_for($contracts,$supplier,$company,(string)$po['order_date']);$covered=$contract!==null;$supplierRow=$suppliers[$supplier]??[];$managed=$covered||in_array((string)($supplierRow['status']??''),['preferred','approved'],true);$emergency=trim((string)($po['expedite_reason']??''))!==''||((string)($po['required_date']??'9999-12-31')<=date('Y-m-d',strtotime((string)$po['order_date'].' +3 days')));if(!isset($cube[$key]))$cube[$key]=['company_id'=>$company,'category_id'=>$category?:null,'supplier_id'=>$supplier,'contract_id'=>$contract['id']??null,'item_id'=>null,'project_workorder_id'=>$po['project_workorder_id']??null,'department_id'=>$po['department_id']??null,'location_id'=>$po['location_id']??null,'buyer_id'=>$po['buyer_id']??null,'business_purpose'=>$po['business_purpose']??'other','ordered_spend'=>0,'received_spend'=>0,'invoiced_spend'=>0,'payment_ready_spend'=>0,'open_commitments'=>0,'contracted_spend'=>0,'off_contract_spend'=>0,'emergency_spend'=>0,'freight_cost'=>0,'quality_cost'=>0,'inventory_carrying_cost'=>0,'addressable_spend'=>0,'spend_under_management'=>0,'spend_under_contract'=>0,'high_risk_spend'=>0];$r=&$cube[$key];$r['ordered_spend']+=$ordered;$r['received_spend']+=$received;$r['open_commitments']+=$open;$r['contracted_spend']+=$covered?$ordered:0;$r['spend_under_contract']+=$covered?$ordered:0;$r['off_contract_spend']+=$covered?0:$ordered;$r['spend_under_management']+=$managed?$ordered:0;$r['emergency_spend']+=$emergency?$ordered:0;$r['addressable_spend']+=$ordered*(($po['business_purpose']??'')==='capital_investment'?0.40:0.85);if(in_array((string)($supplierRow['risk']??''),['high','critical'],true))$r['high_risk_spend']+=$ordered;$poTotal=max(0.01,(float)($po['total_amount']??$ordered));$r['freight_cost']+=(float)($po['freight_amount']??0)*($ordered/$poTotal);unset($r);}
foreach($cube as&$row){$poInvoice=0;$poReady=0;foreach($pos as$po)if((int)$po['company_id']===(int)$row['company_id']&&(int)$po['supplier_id']===(int)$row['supplier_id']){$inv=$invoiceByPo[(int)$po['id']]??null;if($inv){$poInvoice+=(float)$inv['invoiced_spend'];$poReady+=(float)$inv['payment_ready_spend'];}}$row['invoiced_spend']=$poInvoice;$row['payment_ready_spend']=$poReady;$row['inventory_carrying_cost']=round($row['ordered_spend']*0.02,2);foreach($row as$k=>$v)if(is_float($v))$row[$k]=round($v,2);}unset($row);return array_values($cube);
}
function spend_strategy_portfolio_metrics(array $cube,?array $targets=null):array{$sum=static fn(string $field):float=>array_sum(array_map(static fn(array $r):float=>(float)($r[$field]??0),$cube));$spend=$sum('ordered_spend');$supplierTotals=[];foreach($cube as$r)$supplierTotals[(int)$r['supplier_id']]=($supplierTotals[(int)$r['supplier_id']]??0)+(float)$r['ordered_spend'];rsort($supplierTotals);$concentration=$spend>0?($supplierTotals[0]??0)/$spend*100:0;$validated=array_sum(spend_strategy_validated_savings_by_category());$strategies=spend_strategy_strategies();$approved=count(array_filter($strategies,static fn(array $s):bool=>in_array((string)$s['status'],['approved','locked'],true)));return['total_spend'=>$spend,'received_spend'=>$sum('received_spend'),'invoiced_spend'=>$sum('invoiced_spend'),'open_commitments'=>$sum('open_commitments'),'addressable_spend'=>$sum('addressable_spend'),'spend_under_contract'=>$sum('spend_under_contract'),'spend_under_management'=>$sum('spend_under_management'),'off_contract_spend'=>$sum('off_contract_spend'),'emergency_spend'=>$sum('emergency_spend'),'high_risk_spend'=>$sum('high_risk_spend'),'freight_cost'=>$sum('freight_cost'),'inventory_carrying_cost'=>$sum('inventory_carrying_cost'),'validated_savings'=>$validated,'supplier_concentration_pct'=>round($concentration,2),'spend_under_contract_pct'=>$spend>0?round($sum('spend_under_contract')/$spend*100,2):0,'spend_under_management_pct'=>$spend>0?round($sum('spend_under_management')/$spend*100,2):0,'savings_rate_pct'=>$spend>0?round($validated/$spend*100,2):0,'category_plan_completion_pct'=>$strategies?round($approved/count($strategies)*100,2):0];}
function spend_strategy_refresh(string $start,string $end,int $ownerId,int $reviewerId,string $note):array{if($ownerId===$reviewerId)throw new RuntimeException('The snapshot owner and reviewer must be different users.');$cube=spend_strategy_build_cube($start,$end);$period=date('Y-m',strtotime($end));$rows=[];$counter=1;foreach($cube as$row){$row=array_replace($row,['id'=>null,'snapshot_number'=>'SPN-'.date('Ym',strtotime($end)).'-'.str_pad((string)$counter++,4,'0',STR_PAD_LEFT),'period_start'=>$start,'period_end'=>$end,'fiscal_year'=>(int)date('Y',strtotime($end)),'fiscal_period'=>$period,'source_hash'=>hash('sha256',json_encode($row)),'status'=>'draft','owner_id'=>$ownerId,'reviewer_id'=>$reviewerId,'approval_id'=>null,'evidence_note'=>$note]);$rows[]=$row;}spend_strategy_replace_snapshots($rows,$start,$end);foreach(spend_strategy_snapshots()as$snapshot)if(($snapshot['period_start']??'')===$start&&($snapshot['period_end']??'')===$end)spend_strategy_generate_classifications($snapshot,$cube);spend_strategy_add_event(current_company_id()==='enterprise'?null:(int)current_company_id(),'spend_snapshot',0,'snapshot_refreshed',null,'draft','medium',array_sum(array_column($cube,'ordered_spend')),$note);return$rows;}
function spend_strategy_generate_classifications(array $snapshot,array $cube):void{$total=array_sum(array_column($cube,'ordered_spend'));$amount=(float)$snapshot['ordered_spend'];$types=[];if((float)$snapshot['off_contract_spend']>0)$types[]=['off_contract','high',(float)$snapshot['off_contract_spend'],'Purchasing activity lacks confirmed contract coverage.'];if((float)$snapshot['emergency_spend']>0)$types[]=['emergency','high',(float)$snapshot['emergency_spend'],'Expedited or compressed-required-date purchasing requires review.'];if((float)$snapshot['high_risk_spend']>0)$types[]=['high_risk_supplier','critical',(float)$snapshot['high_risk_spend'],'Spend is exposed to a high- or critical-risk supplier.'];if($amount>0&&$amount<max(5000,$total*0.02))$types[]=['tail_spend','medium',$amount,'Low-value fragmented spend may be consolidated or cataloged.'];foreach($types as[$type,$severity,$value,$rationale])spend_strategy_save_classification(['id'=>null,'snapshot_id'=>$snapshot['id'],'company_id'=>$snapshot['company_id'],'classification_type'=>$type,'severity'=>$severity,'amount'=>$value,'rationale'=>$rationale,'root_cause'=>'','owner_id'=>$snapshot['owner_id'],'status'=>'open','due_date'=>date('Y-m-d',strtotime('+30 days')),'resolution_note'=>'']);}
function spend_strategy_category_profile(int $categoryId,array $cube):array{$rows=array_values(array_filter($cube,static fn(array $r):bool=>(int)($r['category_id']??0)===$categoryId));$m=spend_strategy_portfolio_metrics($rows);$supplierTotals=[];foreach($rows as$r)$supplierTotals[(int)$r['supplier_id']]=($supplierTotals[(int)$r['supplier_id']]??0)+(float)$r['ordered_spend'];rsort($supplierTotals);$m['supplier_count']=count($supplierTotals);$m['concentration_pct']=$m['total_spend']>0?round(($supplierTotals[0]??0)/$m['total_spend']*100,2):0;$m['validated_savings']=(float)(spend_strategy_validated_savings_by_category()[$categoryId]??0);return$m;}
function spend_strategy_submit_strategy(array $strategy):array{if(!in_array((string)$strategy['status'],['draft','changes_requested'],true))throw new RuntimeException('Only draft or changes-requested strategies can be submitted.');if((int)$strategy['owner_id']===(int)$strategy['reviewer_id'])throw new RuntimeException('Strategy owner and reviewer must be different users.');$approval=data_upsert('workflow_approvals',['id'=>null,'company_id'=>$strategy['company_id'],'module'=>'strategy','entity_type'=>'category_strategy','entity_id'=>$strategy['id'],'title'=>$strategy['title'],'submitted_by'=>(int)current_user()['id'],'assigned_to'=>$strategy['reviewer_id'],'status'=>'pending','submitted_at'=>date('Y-m-d H:i:s'),'due_date'=>$strategy['review_date'],'notes'=>$strategy['evidence_note']]);$from=$strategy['status'];$strategy['status']='submitted';$strategy['approval_id']=$approval['id'];$strategy['submitted_at']=date('Y-m-d H:i:s');$saved=spend_strategy_save_strategy($strategy);spend_strategy_add_event($strategy['company_id'],'category_strategy',$strategy['id'],'strategy_submitted',$from,'submitted','medium',$strategy['current_spend'],$strategy['evidence_note']);return$saved;}
function spend_strategy_approve_strategy(array $strategy,string $note):array{if((string)$strategy['status']!=='submitted')throw new RuntimeException('Only submitted strategies can be approved.');if((int)current_user()['id']===(int)$strategy['owner_id'])throw new RuntimeException('Strategy owners cannot approve their own strategy.');$strategy['status']='locked';$strategy['approved_at']=date('Y-m-d H:i:s');$strategy['locked_at']=$strategy['approved_at'];$saved=spend_strategy_save_strategy($strategy);if(!empty($strategy['approval_id'])){$approval=data_find('workflow_approvals',(int)$strategy['approval_id']);if($approval){$approval['status']='approved';$approval['notes']=$note;data_upsert('workflow_approvals',$approval);}}spend_strategy_add_event($strategy['company_id'],'category_strategy',$strategy['id'],'strategy_locked','submitted','locked','medium',$strategy['current_spend'],$note);return$saved;}
function spend_strategy_target_actual(string $metric,array $metrics):float{return match($metric){'total_spend'=>(float)$metrics['total_spend'],'addressable_spend'=>(float)$metrics['addressable_spend'],'spend_under_contract_pct'=>(float)$metrics['spend_under_contract_pct'],'off_contract_spend'=>(float)$metrics['off_contract_spend'],'validated_savings'=>(float)$metrics['validated_savings'],'supplier_concentration_pct'=>(float)$metrics['supplier_concentration_pct'],'high_risk_spend'=>(float)$metrics['high_risk_spend'],'category_plan_completion_pct'=>(float)$metrics['category_plan_completion_pct'],default=>0.0};}
function spend_strategy_recalculate_target(array $target,array $metrics):array{$actual=spend_strategy_target_actual((string)$target['metric_code'],$metrics);$targetValue=(float)$target['target_value'];$variance=$actual-$targetValue;$pct=abs($targetValue)>0?$variance/abs($targetValue)*100:0;$tolerance=(float)($target['tolerance_pct']??5);$target['actual_value']=round($actual,2);$target['variance_value']=round($variance,2);$target['variance_pct']=round($pct,2);$target['status']=abs($pct)<=$tolerance?'on_track':(abs($pct)<=$tolerance*2?'watch':'material_variance');return$target;}
function spend_strategy_submit_plan(array $plan,array $metrics):array{if(!in_array((string)$plan['status'],['draft','changes_requested'],true))throw new RuntimeException('Only draft or changes-requested plans can be submitted.');if((int)$plan['owner_id']===(int)$plan['reviewer_id'])throw new RuntimeException('Plan owner and reviewer must be different users.');$targets=spend_strategy_targets((int)$plan['id']);if(!$targets)throw new RuntimeException('At least one governed target is required.');foreach($targets as$target){$target=spend_strategy_recalculate_target($target,$metrics);spend_strategy_save_target($target);if($target['status']==='material_variance'&&(trim((string)$target['root_cause'])===''||trim((string)$target['corrective_action'])===''||trim((string)$target['evidence_note'])===''))throw new RuntimeException('Material variances require root cause, corrective action, and evidence.');}$approval=data_upsert('workflow_approvals',['id'=>null,'company_id'=>$plan['company_id'],'module'=>'strategy','entity_type'=>'procurement_plan','entity_id'=>$plan['id'],'title'=>$plan['period_label'].' procurement plan','submitted_by'=>(int)current_user()['id'],'assigned_to'=>$plan['reviewer_id'],'status'=>'pending','submitted_at'=>date('Y-m-d H:i:s'),'due_date'=>$plan['period_end'],'notes'=>$plan['evidence_note']]);$plan['status']='submitted';$plan['approval_id']=$approval['id'];$plan['submitted_at']=date('Y-m-d H:i:s');$saved=spend_strategy_save_plan($plan);spend_strategy_add_event($plan['company_id'],'procurement_plan',$plan['id'],'plan_submitted','draft','submitted','medium',0,$plan['evidence_note']);return$saved;}
function spend_strategy_approve_plan(array $plan,string $note):array{if((string)$plan['status']!=='submitted')throw new RuntimeException('Only submitted plans can be approved.');if((int)current_user()['id']===(int)$plan['owner_id'])throw new RuntimeException('Plan owners cannot approve their own plan.');$plan['status']='locked';$plan['approved_at']=date('Y-m-d H:i:s');$plan['locked_at']=$plan['approved_at'];$saved=spend_strategy_save_plan($plan);if(!empty($plan['approval_id'])){$approval=data_find('workflow_approvals',(int)$plan['approval_id']);if($approval){$approval['status']='approved';$approval['notes']=$note;data_upsert('workflow_approvals',$approval);}}spend_strategy_add_event($plan['company_id'],'procurement_plan',$plan['id'],'plan_locked','submitted','locked','medium',0,$note);return$saved;}
function spend_strategy_csv_cell(string $value):string{return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;}
